/**
 * Extracted reference artwork (ADR-0004), generated by scripts/extract-art.py.
 * `?no-inline` keeps each WebP a separately cached file instead of base64 inside the JS bundle.
 */
import manifest from '../../art/manifest.json';
import collectorFrame from '../../art/collector-frame.webp?no-inline';
import logoTile from '../../art/logo-tile.webp?no-inline';
import orchardHero from '../../art/orchard-hero.webp?no-inline';
import orchardTreeBlossom from '../../art/orchard-tree-blossom.webp?no-inline';
import orchardTreeSunglasses from '../../art/orchard-tree-sunglasses.webp?no-inline';
import orchardTreeWinter from '../../art/orchard-tree-winter.webp?no-inline';
import orchardTree from '../../art/orchard-tree.webp?no-inline';
import platformTile from '../../art/platform-tile.webp?no-inline';
import shapeCube from '../../art/shape-cube.webp?no-inline';
import shapeGem from '../../art/shape-gem.webp?no-inline';
import shapePyramid from '../../art/shape-pyramid.webp?no-inline';
import shapeSphere from '../../art/shape-sphere.webp?no-inline';
import sorter from '../../art/sorter.webp?no-inline';
import squareHoleBox from '../../art/square-hole-box.webp?no-inline';

export type CastId = 'sorter' | 'coin' | 'collector' | 'stonk';

export interface ArtAsset {
  readonly id: string;
  readonly src: string;
  /** Native pixel size of the crop. Never display larger than this. */
  readonly width: number;
  readonly height: number;
  /** Description of the picture; empty for purely decorative assets. */
  readonly alt: string;
  readonly cast: CastId | null;
}

export interface CastMember {
  readonly id: CastId;
  readonly name: string;
  readonly role: string;
}

const FILES: Readonly<Record<string, string>> = {
  'collector-frame.webp': collectorFrame,
  'logo-tile.webp': logoTile,
  'orchard-hero.webp': orchardHero,
  'orchard-tree-blossom.webp': orchardTreeBlossom,
  'orchard-tree-sunglasses.webp': orchardTreeSunglasses,
  'orchard-tree-winter.webp': orchardTreeWinter,
  'orchard-tree.webp': orchardTree,
  'platform-tile.webp': platformTile,
  'shape-cube.webp': shapeCube,
  'shape-gem.webp': shapeGem,
  'shape-pyramid.webp': shapePyramid,
  'shape-sphere.webp': shapeSphere,
  'sorter.webp': sorter,
  'square-hole-box.webp': squareHoleBox,
};

const CAST_IDS: readonly CastId[] = ['sorter', 'coin', 'collector', 'stonk'];
const isCastId = (value: unknown): value is CastId => CAST_IDS.includes(value as CastId);

/** Assets whose file is bundled. A manifest entry without a file is treated as unavailable, never guessed. */
export const ART: ReadonlyMap<string, ArtAsset> = new Map(
  manifest.assets.flatMap((asset): [string, ArtAsset][] => {
    const src = FILES[asset.output];
    if (!src) return [];
    return [
      [
        asset.id,
        Object.freeze({
          id: asset.id,
          src,
          width: asset.width,
          height: asset.height,
          alt: asset.alt,
          cast: isCastId(asset.cast) ? asset.cast : null,
        }),
      ],
    ];
  }),
);

/** The platform cast (ADR-0004). Storytelling roles only: owning a character never changes fees or rewards. */
export const CAST: readonly CastMember[] = Object.freeze([
  { id: 'sorter', name: 'The Sorter', role: 'Guides the launch flow and empty states' },
  { id: 'coin', name: 'The Coin', role: 'Introduces token launches' },
  { id: 'collector', name: 'The Collector', role: 'Introduces NFT collections and fractions' },
  { id: 'stonk', name: 'The Stonk', role: 'Introduces stock-linked quote assets' },
]);

export function castMember(id: CastId): CastMember {
  const member = CAST.find((c) => c.id === id);
  if (!member) throw new Error(`Unknown cast member ${id}`);
  return member;
}

/** Extracted art for a cast member, or null while original art is pending. */
export function castArt(id: CastId): ArtAsset | null {
  for (const asset of ART.values()) if (asset.cast === id) return asset;
  return null;
}
